window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-df123238950bd735"]={"versions": [{"id": "FIG-df123238950bd735", "releases": ["R20-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">AUTOSAR-ECU-Konfigurationsdiagramm (ECUC Parameter Definition) kombiniert mit begleitenden Parameterspezifikationstabellen für das BSW-Modul Dem (Diagnostic Event Manager). Dargestellt ist die Konfigurationsstruktur der zählerbasierten Ereignis-Entprellung (<code>DemDebounceCounterBased</code>) innerhalb der Klassenauswahl <code>DemDebounceAlgorithmClass</code> sowie deren Verweis auf Entprellklassen-Definitionen.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm spezifiziert folgende Konfigurationselemente und Beziehungen:</p>\n<ul class=\"fig-list\">\n<li>Container <code>DemDebounceAlgorithmClass</code> (<code>EcucChoiceContainerDef</code>, Multiplizität 1..1): Übergeordneter Choice-Container zur Auswahl des Entprellalgorithmus.</li>\n<li>Container <code>DemDebounceCounterBased</code> (<code>EcucParamConfContainerDef</code>, Multiplizität 0..1): Choice-Option (<code>+choice</code>) zur zählerbasierten Entprellung.</li>\n<li>Referenzparameter <code>DemDebounceCounterBasedClassRef</code> (<code>EcucReferenceDef</code>, Multiplizität 1..1, SWS Item <code>[ECUC_Dem_00883]</code>): Gehört per Komposition (<code>+reference</code>) zu <code>DemDebounceCounterBased</code> und verweist (<code>+destination</code>) auf eine Entprellklasse.</li>\n<li>Zielcontainer <code>DemDebounceCounterBasedClass</code> (<code>EcucParamConfContainerDef</code>, Multiplizität 0..65535): Enthält die wiederverwendbaren zählerbasierten Entprellparameter.</li>\n</ul>\n<p class=\"fig-p\">Tabellarische Parameterattribute für <code>DemDebounceCounterBasedClassRef</code>:</p>\n<ul class=\"fig-list\">\n<li>Typ: Reference to <code>DemDebounceCounterBasedClass</code></li>\n<li>Post-Build Variant Value: <code>false</code></li>\n<li>Value Configuration Class: Pre-compile time (<code>X</code> für All Variants), Link time (<code>–</code>), Post-build time (<code>–</code>)</li>\n<li>Included Containers: Keine (<code>No Included Containers</code>).</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Metamodell ohne Ausführungssequenz. Zur Konfigurationszeit wählt eine Dem-Event-Konfiguration über den Choice-Container <code>DemDebounceAlgorithmClass</code> die Variante <code>DemDebounceCounterBased</code> aus. Über die 1:1-Referenz <code>DemDebounceCounterBasedClassRef</code> wird dem Diagnose-Event genau eine der global definierten Konfigurationsklassen aus <code>DemDebounceCounterBasedClass</code> zugewiesen, welche Zählergrenzen und Schrittweiten vorgibt.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Verbindliche ECUC-Strukturdefinition für Generatoren und Konfigurationswerkzeuge des DEM. Die Auswahl von <code>DemDebounceCounterBased</code> ist optional innerhalb des Choice-Containers (0..1), erfordert bei Auswahl jedoch zwingend genau eine gültige Referenz (<code>DemDebounceCounterBasedClassRef</code>, Multiplizität 1..1) auf eine existierende Instanz von <code>DemDebounceCounterBasedClass</code>. Da <code>Post-Build Variant Value</code> auf <code>false</code> und die Konfigurationsklasse ausschließlich auf <code>Pre-compile time</code> festgelegt ist, muss die Referenzauflösung vor dem Kompilieren erfolgen und ist nicht post-build- oder link-time-variabel.</p>"}, {"id": "FIG-7bdebcde7104dfdf", "releases": ["R21-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">AUTOSAR-ECU-Konfigurationsdiagramm (ECUC Parameter Definition) kombiniert mit begleitenden Parameterspezifikationstabellen für das BSW-Modul Dem (Diagnostic Event Manager). Dargestellt ist die Konfigurationsstruktur der zählerbasierten Ereignis-Entprellung (<code>DemDebounceCounterBased</code>) innerhalb der Klassenauswahl <code>DemDebounceAlgorithmClass</code> sowie deren Verweis auf Entprellklassen-Definitionen.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm spezifiziert folgende Konfigurationselemente und Beziehungen:</p>\n<ul class=\"fig-list\">\n<li>Container <code>DemDebounceAlgorithmClass</code> (<code>EcucChoiceContainerDef</code>, Multiplizität 1..1): Übergeordneter Choice-Container zur Auswahl des Entprellalgorithmus.</li>\n<li>Container <code>DemDebounceCounterBased</code> (<code>EcucParamConfContainerDef</code>, Multiplizität 0..1, SWS Item <code>[ECUC_Dem_00711]</code>): Choice-Option (<code>+choice</code>) zur zählerbasierten Entprellung.</li>\n<li>Referenzparameter <code>DemDebounceCounterBasedClassRef</code> (<code>EcucReferenceDef</code>, Multiplizität 1..1, SWS Item <code>[ECUC_Dem_00883]</code>): Gehört per Komposition (<code>+reference</code>) zu <code>DemDebounceCounterBased</code> und verweist (<code>+destination</code>) auf eine Entprellklasse.</li>\n<li>Zielcontainer <code>DemDebounceCounterBasedClass</code> (<code>EcucParamConfContainerDef</code>, Multiplizität 0..65535): Enthält die wiederverwendbaren zählerbasierten Entprellparameter.</li>\n</ul>\n<p class=\"fig-p\">Tabellarische Parameterattribute für <code>DemDebounceCounterBasedClassRef</code>:</p>\n<ul class=\"fig-list\">\n<li>Typ: Reference to <code>DemDebounceCounterBasedClass</code></li>\n<li>Post-Build Variant Value: <code>false</code></li>\n<li>Value Configuration Class: Pre-compile time (<code>X</code> für All Variants), Link time (<code>–</code>), Post-build time (<code>–</code>)</li>\n<li>Included Containers: Keine (<code>No Included Containers</code>).</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Metamodell ohne Ausführungssequenz. Zur Konfigurationszeit wählt eine Dem-Event-Konfiguration über den Choice-Container <code>DemDebounceAlgorithmClass</code> die Variante <code>DemDebounceCounterBased</code> aus. Über die 1:1-Referenz <code>DemDebounceCounterBasedClassRef</code> wird dem Diagnose-Event genau eine der global definierten Konfigurationsklassen aus <code>DemDebounceCounterBasedClass</code> zugewiesen, welche Zählergrenzen und Schrittweiten vorgibt.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Verbindliche ECUC-Strukturdefinition für Generatoren und Konfigurationswerkzeuge des DEM. Die Auswahl von <code>DemDebounceCounterBased</code> ist optional innerhalb des Choice-Containers (0..1), erfordert bei Auswahl jedoch zwingend genau eine gültige Referenz (<code>DemDebounceCounterBasedClassRef</code>, Multiplizität 1..1) auf eine existierende Instanz von <code>DemDebounceCounterBasedClass</code>. Da <code>Post-Build Variant Value</code> auf <code>false</code> und die Konfigurationsklasse ausschließlich auf <code>Pre-compile time</code> festgelegt ist, muss die Referenzauflösung vor dem Kompilieren erfolgen und ist nicht post-build- oder link-time-variabel.</p>"}, {"id": "FIG-4839bf087922f10d", "releases": ["R22-11", "R23-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">AUTOSAR-ECU-Konfigurationsdiagramm (ECUC Parameter Definition) kombiniert mit begleitenden Parameterspezifikationstabellen für das BSW-Modul Dem (Diagnostic Event Manager). Dargestellt ist die Konfigurationsstruktur der zählerbasierten Ereignis-Entprellung (<code>DemDebounceCounterBased</code>) innerhalb der Klassenauswahl <code>DemDebounceAlgorithmClass</code> sowie deren Verweis auf Entprellklassen-Definitionen.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm spezifiziert folgende Konfigurationselemente und Beziehungen:</p>\n<ul class=\"fig-list\">\n<li>Container <code>DemDebounceAlgorithmClass</code> (<code>EcucChoiceContainerDef</code>, Multiplizität 1..1): Übergeordneter Choice-Container zur Auswahl des Entprellalgorithmus.</li>\n<li>Container <code>DemDebounceCounterBased</code> (<code>EcucParamConfContainerDef</code>, Multiplizität 0..1, SWS Item <code>[ECUC_Dem_00711]</code>): Choice-Option (<code>+choice</code>) zur zählerbasierten Entprellung.</li>\n<li>Referenzparameter <code>DemDebounceCounterBasedClassRef</code> (<code>EcucReferenceDef</code>, Multiplizität 1..1, SWS Item <code>[ECUC_Dem_00883]</code>): Gehört per Komposition (<code>+reference</code>) zu <code>DemDebounceCounterBased</code> und verweist (<code>+destination</code>) auf eine Entprellklasse.</li>\n<li>Zielcontainer <code>DemDebounceCounterBasedClass</code> (<code>EcucParamConfContainerDef</code>, Multiplizität 0..65535): Enthält die wiederverwendbaren zählerbasierten Entprellparameter.</li>\n</ul>\n<p class=\"fig-p\">Tabellarische Parameterattribute für <code>DemDebounceCounterBasedClassRef</code>:</p>\n<ul class=\"fig-list\">\n<li>Typ: Reference to <code>DemDebounceCounterBasedClass</code></li>\n<li>Post-Build Variant Value: <code>false</code></li>\n<li>Value Configuration Class: Pre-compile time (<code>X</code> für All Variants), Link time (<code>–</code>), Post-build time (<code>–</code>)</li>\n<li>Included Containers: Keine (<code>No Included Containers</code>).</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Metamodell ohne Ausführungssequenz. Zur Konfigurationszeit wählt eine Dem-Event-Konfiguration über den Choice-Container <code>DemDebounceAlgorithmClass</code> die Variante <code>DemDebounceCounterBased</code> aus. Über die 1:1-Referenz <code>DemDebounceCounterBasedClassRef</code> wird dem Diagnose-Event genau eine der global definierten Konfigurationsklassen aus <code>DemDebounceCounterBasedClass</code> zugewiesen, welche Zählergrenzen und Schrittweiten vorgibt.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Verbindliche ECUC-Strukturdefinition für Generatoren und Konfigurationswerkzeuge des DEM. Die Auswahl von <code>DemDebounceCounterBased</code> ist optional innerhalb des Choice-Containers (0..1), erfordert bei Auswahl jedoch zwingend genau eine gültige Referenz (<code>DemDebounceCounterBasedClassRef</code>, Multiplizität 1..1) auf eine existierende Instanz von <code>DemDebounceCounterBasedClass</code>. Da <code>Post-Build Variant Value</code> auf <code>false</code> und die Konfigurationsklasse ausschließlich auf <code>Pre-compile time</code> festgelegt ist, muss die Referenzauflösung vor dem Kompilieren erfolgen und ist nicht post-build- oder link-time-variabel.</p>"}, {"id": "FIG-7cfeffba31bff01e", "releases": ["R24-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">AUTOSAR-ECU-Konfigurationsdiagramm (UML-Klassendiagramm der ECUC Parameter Definition) für das BSW-Modul Dem (Diagnostic Event Manager). Dargestellt ist die Modellstruktur für die zählerbasierte Ereignis-Entprellung (<code>DemDebounceCounterBased</code>) als Spezialisierung der Klassenauswahl <code>DemDebounceAlgorithmClass</code> sowie deren Referenzbeziehung zu <code>DemDebounceCounterBasedClass</code>.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Klassendiagramm spezifiziert folgende Konfigurationscontainer und Beziehungen:</p>\n<ul class=\"fig-list\">\n<li>Container <code>DemDebounceAlgorithmClass: EcucChoiceContainerDef</code> mit Multiplizität <code>lowerMultiplicity = 1</code>, <code>upperMultiplicity = 1</code>.</li>\n<li>Container <code>DemDebounceCounterBased: EcucParamConfContainerDef</code> mit Multiplizität <code>lowerMultiplicity = 0</code>, <code>upperMultiplicity = 1</code>, eingebunden über eine Choice-Aggregation (<code>+choice</code>).</li>\n<li>Referenzelement <code>DemDebounceCounterBasedClassRef: EcucReferenceDef</code> mit Multiplizität <code>lowerMultiplicity = 1</code>, <code>upperMultiplicity = 1</code>, verknüpft per Komposition (<code>+reference</code>) an <code>DemDebounceCounterBased</code>.</li>\n<li>Zielcontainer <code>DemDebounceCounterBasedClass: EcucParamConfContainerDef</code> mit Multiplizität <code>lowerMultiplicity = 0</code>, <code>upperMultiplicity = 65535</code>, adressiert über die gerichtete Referenzassoziation (<code>+destination</code>).</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Metamodell ohne Ausführungssequenz. Zur Konfigurationszeit wählt eine Dem-Event-Konfiguration über den Choice-Container <code>DemDebounceAlgorithmClass</code> die Variante <code>DemDebounceCounterBased</code> aus. Über die 1:1-Referenz <code>DemDebounceCounterBasedClassRef</code> wird dem Diagnose-Event genau eine der global definierten Konfigurationsklassen aus <code>DemDebounceCounterBasedClass</code> zugewiesen, welche Zählergrenzen und Schrittweiten vorgibt.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normative Metamodell-Vorgabe für ECUC-Beschreibungsdateien und Konfigurationswerkzeuge des Dem. Innerhalb von <code>DemDebounceAlgorithmClass</code> darf maximal eine <code>DemDebounceCounterBased</code>-Instanz gewählt werden. Ist diese aktiv, muss exakt eine Referenz <code>DemDebounceCounterBasedClassRef</code> auf eine der bis zu 65535 im System definierten <code>DemDebounceCounterBasedClass</code>-Instanzen verweisen.</p>"}, {"id": "FIG-1041e55982ecabaf", "releases": ["R25-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">AUTOSAR-ECU-Konfigurationsdiagramm (UML-Klassendiagramm der ECUC Parameter Definition) für das BSW-Modul Dem (Diagnostic Event Manager). Dargestellt ist die Modellstruktur für die zählerbasierte Ereignis-Entprellung (<code>DemDebounceCounterBased</code>) als Spezialisierung der Klassenauswahl <code>DemDebounceAlgorithmClass</code> sowie deren Referenzbeziehung zu <code>DemDebounceCounterBasedClass</code>.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Klassendiagramm spezifiziert folgende Konfigurationscontainer und Beziehungen:</p>\n<ul class=\"fig-list\">\n<li>Container <code>DemDebounceAlgorithmClass: EcucChoiceContainerDef</code> mit Multiplizität <code>lowerMultiplicity = 1</code>, <code>upperMultiplicity = 1</code>.</li>\n<li>Container <code>DemDebounceCounterBased: EcucParamConfContainerDef</code> mit Multiplizität <code>lowerMultiplicity = 0</code>, <code>upperMultiplicity = 1</code>, eingebunden über eine Choice-Aggregation (<code>+choice</code>).</li>\n<li>Referenzelement <code>DemDebounceCounterBasedClassRef: EcucReferenceDef</code> mit Multiplizität <code>lowerMultiplicity = 1</code>, <code>upperMultiplicity = 1</code>, verknüpft per Komposition (<code>+reference</code>) an <code>DemDebounceCounterBased</code>.</li>\n<li>Zielcontainer <code>DemDebounceCounterBasedClass: EcucParamConfContainerDef</code> mit Multiplizität <code>lowerMultiplicity = 0</code>, <code>upperMultiplicity = 65535</code>, adressiert über die gerichtete Referenzassoziation (<code>+destination</code>).</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Metamodell ohne Ausführungssequenz. Zur Konfigurationszeit wählt eine Dem-Event-Konfiguration über den Choice-Container <code>DemDebounceAlgorithmClass</code> die Variante <code>DemDebounceCounterBased</code> aus. Über die 1:1-Referenz <code>DemDebounceCounterBasedClassRef</code> wird dem Diagnose-Event genau eine der global definierten Konfigurationsklassen aus <code>DemDebounceCounterBasedClass</code> zugewiesen, welche Zählergrenzen und Schrittweiten vorgibt.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normative Metamodell-Vorgabe für ECUC-Beschreibungsdateien und Konfigurationswerkzeuge des Dem. Innerhalb von <code>DemDebounceAlgorithmClass</code> darf maximal eine <code>DemDebounceCounterBased</code>-Instanz gewählt werden. Ist diese aktiv, muss exakt eine Referenz <code>DemDebounceCounterBasedClassRef</code> auf eine der bis zu 65535 im System definierten <code>DemDebounceCounterBasedClass</code>-Instanzen verweisen.</p>"}], "trans": [{"from": "FIG-df123238950bd735", "to": "FIG-7bdebcde7104dfdf", "fr": "R20-11", "tr": "R21-11", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\">\n<li>Container <code>DemDebounceCounterBased</code>: Kennung <code>SWS Item [ECUC_Dem_00711]</code> im Tabellenkopf ergänzt.</li>\n</ul>"}, {"from": "FIG-7bdebcde7104dfdf", "to": "FIG-4839bf087922f10d", "fr": "R21-11", "tr": "R22-11", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\">\n<li>Parameter <code>DemDebounceCounterBasedClassRef</code>: Kennung <code>[ECUC_Dem_00883]</code> in eine eigene vorangestellte Zeile <code>SWS Item [ECUC_Dem_00883]</code> ausgelagert und Feldbezeichner <code>Name</code> zu <code>Parameter Name</code> präzisiert.</li>\n</ul>"}, {"from": "FIG-4839bf087922f10d", "to": "FIG-7cfeffba31bff01e", "fr": "R23-11", "tr": "R24-11", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\">\n<li>Gesamte tabellarische Parameterspezifikation (Definitionstabellen für Container <code>DemDebounceCounterBased</code> und Referenzparameter <code>DemDebounceCounterBasedClassRef</code>) sowie Überschrift <code>No Included Containers</code> entfernt; das Schaubild beschränkt sich auf das UML-Klassendiagramm.</li>\n</ul>"}, {"from": "FIG-7cfeffba31bff01e", "to": "FIG-1041e55982ecabaf", "fr": "R24-11", "tr": "R25-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
